// keys: "abq"
// expect: exit 3
// screen: 0 3 keys
int main(void)
{
    int n = 0, k;
    cls();
    do {
        k = getkey();
        n++;
    } while (k != 'q');
    printf("%d keys\n", n);
    return n;
}
